begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select plan(19);
select isnt(has_function_privilege('anon','public.complete_quest(uuid,uuid)','EXECUTE'),true,'SQ-0503 denies anonymous completion');select ok(has_function_privilege('authenticated','public.complete_quest(uuid,uuid)','EXECUTE'),'SQ-0503 grants authenticated RPC');select ok(position('quest_level_for_xp' in pg_get_functiondef('public.complete_quest(uuid,uuid)'::regprocedure))>0,'SQ-0503 uses SQ-0601 contract');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('05030000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','complete@example.test','','{}','{"display_name":"Complete User"}',now(),now()),('05030000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','other@example.test','','{}','{"display_name":"Other"}',now(),now());
insert into public.categories(slug,name_key,is_enabled)values('chill','categories.chill',true)on conflict(slug)do update set is_enabled=true;
insert into public.quest_templates(id,template_family_id,version,category_id,title,description,instructions,duration_min,duration_max,estimated_cost_min,estimated_cost_max,currency_code,difficulty,base_xp,location_mode,physical_demand,safety_notes,moderation_status,enabled_at)select'05030000-0000-4000-8000-000000000101','05030000-0000-4000-8000-000000000201',1,id,'Fixture','Description','["Step"]',30,30,0,0,'IDR','easy',150,'none','Low','Safe','approved',now()-interval'1 day'from public.categories where slug='chill';
insert into public.quest_searches(id,user_id,time_filter,budget_filter,mood_filter,distance_filter,expires_at)values('05030000-0000-4000-8000-000000000301','05030000-0000-4000-8000-000000000001','30_minutes','free','chill','walking',now()+interval'30 min'),('05030000-0000-4000-8000-000000000302','05030000-0000-4000-8000-000000000002','30_minutes','free','chill','walking',now()+interval'30 min');
insert into public.quest_instances(id,user_id,search_id,template_id,status,snapshot,category_id,base_xp,accepted_at)select v.id,v.uid,v.sid,'05030000-0000-4000-8000-000000000101','active','{"title":"Fixture"}',c.id,150,now()from(values('05030000-0000-4000-8000-000000000401'::uuid,'05030000-0000-4000-8000-000000000001'::uuid,'05030000-0000-4000-8000-000000000301'::uuid),('05030000-0000-4000-8000-000000000402','05030000-0000-4000-8000-000000000002','05030000-0000-4000-8000-000000000302'))v(id,uid,sid)cross join public.categories c where c.slug='chill';
insert into public.quest_proofs(id,quest_instance_id,user_id,storage_path,mime_type,byte_size,status)values('05030000-0000-4000-8000-000000000501','05030000-0000-4000-8000-000000000401','05030000-0000-4000-8000-000000000001','path/one.jpg','image/jpeg',100,'uploaded');
select set_config('request.jwt.claim.sub','05030000-0000-4000-8000-000000000001',true);set local role authenticated;
select is(public.complete_quest('05030000-0000-4000-8000-000000000401','05030000-0000-4000-8000-000000000601')->>'outcome','completed','SQ-0503 completes Active Quest');select is((select status::text from public.quest_instances where id='05030000-0000-4000-8000-000000000401'),'completed','SQ-0503 persists Completed');select ok((select completed_at is not null from public.quest_instances where id='05030000-0000-4000-8000-000000000401'),'SQ-0503 records completed_at');
select is((select xp_awarded from public.quest_completions),150,'SQ-0503 awards snapshot XP');select is((select count(*)from public.xp_ledger),1::bigint,'SQ-0503 writes one ledger row');select is((select amount from public.xp_ledger),150,'SQ-0503 ledger has total award');select is((select lifetime_xp from public.user_progress where user_id='05030000-0000-4000-8000-000000000001'),150::bigint,'SQ-0503 updates total XP');select is((select level from public.user_progress where user_id='05030000-0000-4000-8000-000000000001'),2,'SQ-0503 derives level');select is((select completed_count from public.user_progress where user_id='05030000-0000-4000-8000-000000000001'),1,'SQ-0503 increments count');
select is(public.complete_quest('05030000-0000-4000-8000-000000000401','05030000-0000-4000-8000-000000000601')->>'total_xp','150','SQ-0503 same-key replay returns immutable after-total');select is(public.complete_quest('05030000-0000-4000-8000-000000000401','05030000-0000-4000-8000-000000000602')->>'outcome','already_completed','SQ-0503 same-instance different key replays');select is((select count(*)from public.quest_completions),1::bigint,'SQ-0503 has one completion');select is((select count(*)from public.xp_ledger),1::bigint,'SQ-0503 has one award');select throws_ok($$select public.complete_quest('05030000-0000-4000-8000-000000000499','05030000-0000-4000-8000-000000000601')$$,'22023','Completion key is already used','SQ-0503 rejects key reuse');
reset role;select set_config('request.jwt.claim.sub','05030000-0000-4000-8000-000000000002',true);set local role authenticated;select throws_ok($$select public.complete_quest('05030000-0000-4000-8000-000000000402','05030000-0000-4000-8000-000000000603')$$,'P0001','uploaded_proof_required','SQ-0503 requires uploaded proof');select is((select status::text from public.quest_instances where id='05030000-0000-4000-8000-000000000402'),'active','SQ-0503 failed validation rolls back');reset role;select * from finish();rollback;
